class Solution:
    def isPreorder(self, nodes: List[List[int]]) -> bool:
        if nodes[0][1] != -1:
            return False
        st = [[nodes[0][0], 2]]
        for nid, p in nodes[1:]:
            if not st or st[-1][0] != p:
                return False
            st[-1][1] -= 1
            while st and st[-1][1] == 0:
                st.pop()
            st.append([nid, 2])
        return True

