class Solution {
public:
    bool isPreorder(vector<vector<int>>& nodes) {
        if (nodes[0][1] != -1) return false;
        vector<pair<int,int>> st{{nodes[0][0], 2}};
        for (size_t i = 1; i < nodes.size(); ++i) {
            int nid = nodes[i][0], p = nodes[i][1];
            if (st.empty() || st.back().first != p) return false;
            if (--st.back().second == 0) st.pop_back();
            st.push_back({nid, 2});
        }
        return true;
    }
};

