class Solution {
    public boolean isPreorder(List<List<Integer>> nodes) {
        if (nodes.get(0).get(1) != -1) return false;
        Deque<long[]> st = new ArrayDeque<>();
        st.push(new long[]{nodes.get(0).get(0), 2});
        for (int i = 1; i < nodes.size(); i++) {
            int nid = nodes.get(i).get(0), p = nodes.get(i).get(1);
            if (st.isEmpty() || st.peek()[0] != p) return false;
            if (--st.peek()[1] == 0) st.pop();
            st.push(new long[]{nid, 2});
        }
        return true;
    }
}

