class Solution {
public:
    int n;
    vector<vector<int>>* nd;
    int parse(int lo, int par) {
        if (lo >= n || (*nd)[lo][1] != par) return lo;
        int end = parse(lo + 1, (*nd)[lo][0]);
        return parse(end, (*nd)[lo][0]);
    }
    bool isPreorder(vector<vector<int>>& nodes) {
        nd = &nodes; n = nodes.size();
        if (nodes[0][1] != -1) return false;
        return parse(1, nodes[0][0]) == n;
    }
};

